var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
H.move_to("U_NOBZ_A", 40.5, 30.0)
H.move_to("U_ALLARUS_CUSTODIANS_A", 28.0, 40.0)
return H.setup(2, "Lions of the Emperor", {})

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return "U_ALLARUS_CUSTODIANS_A" in RulesEngine.get_eligible_targets("U_NOBZ_A", GameState.state)

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
PhaseManager.transition_to_phase(8)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.assign_and_confirm(1, "U_NOBZ_A", "U_ALLARUS_CUSTODIANS_A")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.phase().awaiting_reactive_stratagem

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return main.get_tree().root.get_node("StratagemDialog/Content/Header").text.contains("targeted")

var main = tree.current_scene
