return H.flag("U_ALLARUS_CUSTODIANS_A", "effect_minus_damage")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return "U_NOBZ_A" in H.flag("U_ALLARUS_CUSTODIANS_A", "cus11e_vigil_unending").get("attackers", [])

